//! Send-first decompression bomb — a fixed, compile-time-constant byte blob
//! written unconditionally on accept, BEFORE reading anything the peer sent.
//!
//! # Safety invariant (zero-parse, root-safe)
//!
//! `BOMB_BODY` is `include_bytes!`'d from a file generated by `build.rs` at
//! `cargo build` time (nested gzip, see that file's doc comment). At runtime
//! this module performs **zero compression or decompression** — it only
//! ever `write_all`s a static byte slice that was already fully computed
//! before the binary was linked. There is no branch on anything the peer
//! sends: the header + body are emitted unconditionally, identically, for
//! every connection routed here. Never decompress anything an attacker
//! sends to us — that direction (zip-bomb-the-defender) is explicitly
//! out of scope and must never be added here.
//!
//! # Default-off
//!
//! This is the most aggressive burn optic (per the grounding survey) — gated
//! by [`bomb_enabled`], default `false`, flipped via the
//! `MIRAGE_SECD_BURN_BOMB_ENABLED` environment variable. Tarpit and
//! junk-flood ship default-usable; the bomb requires an explicit opt-in.

/// The precomputed nested-gzip bomb body, baked in at compile time by
/// `build.rs`. Never decoded, never inspected — sent verbatim.
static BOMB_BODY: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/decoy_bomb.bin"));

/// Environment variable gating the bomb burn mode. Unset or any value other
/// than `"1"`/`"true"` (case-insensitive) leaves the bomb disabled.
pub const BOMB_ENABLED_ENV: &str = "MIRAGE_SECD_BURN_BOMB_ENABLED";

/// Whether the send-first decompression bomb is enabled for this process.
///
/// Read once per connection (cheap `env::var` call) rather than cached —
/// this is not a hot path relative to the bomb write itself, and reading
/// fresh means an operator can flip the env var + restart without any other
/// code change.
#[must_use]
pub fn bomb_enabled() -> bool {
    match std::env::var(BOMB_ENABLED_ENV) {
        Ok(v) => {
            let v = v.trim().to_ascii_lowercase();
            v == "1" || v == "true"
        }
        Err(_) => false,
    }
}

/// Build the fixed HTTP/1.1 response header emitted before the bomb body.
///
/// A CONSTANT byte sequence — computed from `body_len` (our own state, the
/// length of our own precomputed blob) and nothing the peer sent. Emitting a
/// constant is not parsing: no read of the peer's request happens before or
/// during this call.
fn bomb_header(body_len: usize) -> Vec<u8> {
    format!(
        "HTTP/1.1 200 OK\r\n\
         Content-Type: application/octet-stream\r\n\
         Content-Encoding: gzip\r\n\
         Content-Length: {body_len}\r\n\
         Connection: close\r\n\
         \r\n"
    )
    .into_bytes()
}

/// The full fixed response: header + bomb body concatenated, ready to
/// `write_all` unconditionally on accept. Built once lazily and reused for
/// every connection — no per-connection allocation of the (large) body.
pub fn bomb_response() -> &'static [u8] {
    static RESPONSE: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
    RESPONSE.get_or_init(|| {
        let mut out = bomb_header(BOMB_BODY.len());
        out.extend_from_slice(BOMB_BODY);
        out
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bomb_body_is_fixed_size_and_nonempty() {
        assert!(!BOMB_BODY.is_empty(), "bomb body must be generated by build.rs");
        // Keep the wire cost sane: the whole point of a bomb is that OUR
        // egress stays small. A few MiB ceiling catches a build.rs regression
        // that accidentally emits an uncompressed or under-nested blob.
        assert!(
            BOMB_BODY.len() < 8 * 1024 * 1024,
            "bomb body must stay small on the wire (got {} bytes)",
            BOMB_BODY.len()
        );
    }

    #[test]
    fn bomb_header_reports_exact_body_length() {
        let header = bomb_header(BOMB_BODY.len());
        let header_str = String::from_utf8_lossy(&header);
        assert!(header_str.contains(&format!("Content-Length: {}", BOMB_BODY.len())));
        assert!(header_str.contains("Content-Encoding: gzip"));
        assert!(header_str.ends_with("\r\n\r\n"));
    }

    #[test]
    fn bomb_response_is_header_then_body_verbatim() {
        let full = bomb_response();
        assert!(full.ends_with(BOMB_BODY), "response must end with the exact bomb body bytes");
        assert!(full.len() > BOMB_BODY.len(), "response must be longer than the body alone (header present)");
    }

    #[test]
    fn bomb_enabled_defaults_false_when_unset() {
        // SAFETY invariant under test, not an env-mutation hazard: this test
        // only reads, never sets, BOMB_ENABLED_ENV — verifying the
        // default-off contract holds in a clean process environment.
        if std::env::var(BOMB_ENABLED_ENV).is_err() {
            assert!(!bomb_enabled());
        }
    }
}
